    fn transition_to_half_open(&mut self) {
        info!("Circuit breaker transitioning to half-open");
        self.state = CircuitBreakerState::HalfOpen;
        self.last_state_change = Instant::now();
        self.next_attempt = Some(Instant::now());
        self.reset_counters();
