    pub fn get_secret(&self, id: &NodeId) -> Result<SecretEntry, VaultError> {
        let node = self.dag.get_node(id)
            .ok_or(VaultError::SecretNotFound)?;

        // Decrypt
        let plaintext = self.crypto.cipher.decrypt(
