    async fn process_events(&mut self) -> Result<(), DistributedVaultError> {
        let (tx, mut rx) = mpsc::channel(100);

        // Spawn network event handler
        let p2p_handle = self.p2p_node.handle();
        let network_tx = tx.clone();
        tokio::spawn(async move {
