```rust
use qudag_crypto::{CryptoError, KEMError, MlDsaError};

fn handle_crypto_operations() -> Result<(), CryptoError> {
    let kem = MlKem768;

    match kem.keygen() {
        Ok((pk, sk)) => {
            // Use keys
            let (ct, ss) = kem.encap(&pk)?;
            let ss2 = kem.decap(&sk, &ct)?;
            assert_eq!(ss, ss2);
        }
        Err(KEMError::KeyGenError) => {
