    let (kem_pk, kem_sk) = MlKem768::keygen().unwrap();
    let dsa_keypair = MlDsaKeyPair::generate(&mut rng).unwrap();

    // Establish shared secret
    let (ciphertext, shared_secret) = MlKem768::encapsulate(&kem_pk).unwrap();

