class ManagedExchange {
    constructor() {
        this.exchange = new QuDagExchange();

        // Auto-cleanup on page unload
        window.addEventListener('beforeunload', () => {
            this.cleanup();
        });
    }

    cleanup() {
        if (this.exchange) {
            this.exchange.free();
            this.exchange = null;
        }
    }
}
