            Err(error) => {
                error!(self.logger, "MCP request failed";
                    "correlation_id" => correlation_id,
                    "duration_ms" => duration.as_millis(),
                    "error" => %error,
                    "error_type" => error.error_type()
                );
            }
        }
    }

