        .with_max_level(tracing::Level::INFO)
        .with_target(false)
        .without_time()
        .init();

    if is_running_on_lambda() {
        run(service_fn(handler)).await
    } else {
        // Local development server
        lambda_web_run(service_fn(handler)).await
    }
}
