use wasm_bindgen::prelude::*;
use js_sys::{Promise, Uint8Array};

#[wasm_bindgen]
pub struct WasmQuDAG {
    inner: Arc<Mutex<DAGConsensus>>,
    runtime: Option<Runtime>,
