        &self,
        public_key: &MLDSAPublicKey,
        message: &[u8],
        signature: &MLDSASignature,
    ) -> Result<bool, MLDSAError> {
        // Verification is typically not sensitive to side-channels
        ml_dsa_verify(
            &public_key.0,
            message,
            &signature.0,
            self.parameter_set,
        )
    }
