        let ciphertext = if let Some(web_crypto) = &self.web_crypto {
            web_crypto.encrypt_aes_gcm(key, &plaintext, &nonce).await?
        } else {
            self.wasm_crypto.encrypt_aes_gcm(key, &plaintext, &nonce).await?
        };

        Ok(EncryptedEntry {
            nonce,
            ciphertext,
            algorithm: "AES-256-GCM",
        })
    }
}
