    pub fn track_operation<F, R>(&self, operation: &str, f: F) -> R
    where
        F: FnOnce() -> R,
    {
        let start = Instant::now();
        let result = f();
        let duration = start.elapsed();

        let mut metrics = self.metrics.lock().unwrap();
        metrics.record_operation(operation, duration);

